-- DijiMedu okul parkuru: kalıp verisi
-- 1) Öğretmen kararıyla kalıp durağından çıkarılan kayıtlar işaretlenir (artikelsiz doldurma).
-- 2) ChatGPT'nin ürettiği, doğrulamadan geçen 314 kalıp eklenir.
-- Dosya yeniden çalıştırılabilir: önce kendi partisini siler, sonra yeniden ekler.
begin;

update public.word_bank
set extra = coalesce(extra,'{}'::jsonb) || jsonb_build_object(
      'pattern_usable', false,
      'pattern_excluded_reason', 'Bosluga gelen kelime artikelsiz kaliyor; ogretmen karariyla cikarildi 2026-10-20')
where active and extra->>'type'='pattern'
  and position('...' in english) > 0
  and english ~* '\m(got|like|see|want|need|have|wear|feed|buy)\s+\.\.\.';

delete from public.word_bank where extra->>'import_batch' = 'dijimedu_pattern_20261019';


commit;
